package cl.skinspad.reporte.soporte;
import java.util.*;import java.time.*;import jakarta.persistence.EntityManager;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Repository;import static cl.skinspad.reporte.soporte.SoporteDtos.*;
@Repository @RequiredArgsConstructor public class BandejaRepository {
 private final EntityManager em;
 public Pagina buscar(String clase,String estado,String prioridad,String tipo,LocalDate desde,LocalDate hasta,int pagina,int tamano){if(pagina<0||pagina>10000||tamano<1||tamano>100)throw new IllegalArgumentException("Paginación inválida");if(desde!=null&&hasta!=null&&desde.isAfter(hasta))throw new IllegalArgumentException("Rango de fechas inválido");
  String union="(select id, 'REPORTE' as clase, descripcion as titulo,estado,prioridad,tipo_objetivo,fecha_creacion,admin_asignado_id from soporte_reporte) casos";
  var filtros=new LinkedHashMap<String,Object>();String where=" where 1=1";for(var entry:Map.of("clase",clase==null?"":clase,"estado",estado==null?"":estado,"prioridad",prioridad==null?"":prioridad,"tipo_objetivo",tipo==null?"":tipo).entrySet())if(entry.getKey().equals("estado")&&entry.getValue().equals("PENDIENTES")){where+=" and estado in ('ABIERTO','EN_REVISION')";}else if(!entry.getValue().isBlank()){where+=" and "+entry.getKey()+"=:"+entry.getKey();filtros.put(entry.getKey(),entry.getValue());}
  var zona=ZoneId.of("America/Santiago");if(desde!=null){where+=" and fecha_creacion>=:desde";filtros.put("desde",java.sql.Timestamp.from(desde.atStartOfDay(zona).toInstant()));}if(hasta!=null){where+=" and fecha_creacion<:hasta";filtros.put("hasta",java.sql.Timestamp.from(hasta.plusDays(1).atStartOfDay(zona).toInstant()));}
  var count=em.createNativeQuery("select count(*) from "+union+where);var query=em.createNativeQuery("select id,clase,titulo,estado,prioridad,tipo_objetivo,fecha_creacion,admin_asignado_id from "+union+where+" order by case prioridad when 'URGENTE' then 0 when 'ALTA' then 1 else 2 end, fecha_creacion asc,clase,id");filtros.forEach((k,v)->{count.setParameter(k,v);query.setParameter(k,v);});query.setFirstResult(pagina*tamano);query.setMaxResults(tamano);
  List<Object[]> rows=query.getResultList();var datos=rows.stream().map(r->new Fila(((Number)r[0]).longValue(),(String)r[1],((String)r[2]).substring(0,Math.min(160,((String)r[2]).length())),(String)r[3],(String)r[4],(String)r[5],r[6] instanceof java.time.OffsetDateTime z?z.toInstant():r[6] instanceof Instant i?i:r[6] instanceof java.sql.Timestamp t?t.toInstant():((LocalDateTime)r[6]).toInstant(ZoneOffset.UTC),(String)r[7])).toList();return new Pagina(datos,((Number)count.getSingleResult()).longValue(),pagina,tamano);
 }
}
